set -uo pipefail
W=/usr/local/bin/census-batch6L-wait
cp -p $W $W.orig-b4wait
echo  | base64 -d > $W.new && chmod 755 $W.new && bash -n $W.new && mv -f $W.new $W
mkdir -p /etc/cregit-census && touch /etc/cregit-census/batch6L.no-b4-wait
$W --decide-only | cut -c1-400; echo "decide rc=${PIPESTATUS[0]}"
systemctl restart census-batch6L-wait.service; sleep 20
systemctl is-active census-batch6L-wait.service census-batch6L.service; cat /run/census-batch6L-wait.status | cut -c1-400
